solution.code:
#include <stdio.h>

struct Rect {
    int width;
    int height;
};

void scale(struct Rect *r, int factor) {
    r->width *= factor;
    r->height *= factor;
}

int main() {
    struct Rect r = {4, 3};
    scale(&r, 3);
    printf("%d x %d\n", r.width, r.height);
    return 0;
}
